.ziwang {
  width: 100%;
  display: flex;
  padding-left: 16px;

  .el-aside {
    width: 200px !important;
    overflow-x: auto
  }

  .ziwang_r {
    flex: 1;
    overflow: hidden;
  }
}

::v-deep .el-tree {
  background: transparent;
  color: #46506d;
}

::v-deep .el-tree-node.is-current > .el-tree-node__content {
  background: none
}

::v-deep .el-tree--highlight-current .el-tree-node.is-current > .el-tree-node__content {
  background: none
}

::v-deep .el-tree-node__content:hover {
  background: none
}

.xt-layout-sider {
  background-color: #cfe6f9;
  border-radius: 5px;
  height: 100%;
}

::v-deep .el-tree-node__label {
  padding-right: 10px;
}

::v-deep .el-tabs__item {
  height: 20px;
  line-height: 20px;
}

::v-deep .el-tabs__nav {
  padding-bottom: 10px;
}

::v-deep .list_btn {
  padding: 9px 5px !important;
}

::v-deep .btn_red {
  color: red;
}

.title_line {

  position: relative;
  padding-left: 15px;
  font-size: 15px;
  font-weight: bold;
  height: 20px;

  &::before {
    content: '';
    position: absolute;
    left: 0px;
    width: 0px;
    height: 100%;
    border-left: 4px solid;
    z-index: 9;
    margin-right: 4px;
    color: #409EFF;
  }


}
